contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        vm.assume(caller != address(0));
        unlockTime = bound(unlockTime, 0, block.timestamp + 1000);
        putAmount = bound(putAmount, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, 100 ether);

        // Set up caller and fund if needed
        vm.deal(caller, putAmount + collectAmount);

        // Call Put to deposit
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Try to collect
        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Check that balance never overflows: if Collect succeeded, then after collecting,
        // the remaining balance must be >= 0, which is always true, but the invariant is:
        // the balance before Collect plus MinSum must not overflow.
        // Actually the invariant that holds for the reference: 
        // If Collect reverts, it's fine. If it succeeds, we check that balance does not exceed max uint - MinSum.
        uint256 balance = c.Acc(caller).balance;
        // The general rule: if Collect was called with collectAmount, 
        // then the resulting balance is such that balance + MinSum >= balance (no overflow)
        // which is always true for uint. But the mutant changes the overflow check in Put.
        // The real difference: For the reference, after any sequence ending with Collect,
        // it holds that (balance + MinSum >= balance) i.e. no overflow will occur on next Put.
        // The mutant's Put will revert if balance + value > balance (i.e. overflow) instead of >=
        // which is exactly the same as checking overflow, so the condition is actually equivalent.
